[SPECIALIST_FINDING]
{
  "specialty": "kdoctor-hematology-oncology",
  "answer": "수 주간 피로 + 자연 발생 멍 + 무통성 경부 림프절 종대의 조합은 급성 백혈병·골수기능부전·림프종(골수 침범 동반) 같은 혈액종양 질환을 대면 평가 없이 배제할 수 없는 조합입니다. 확정 진단은 불가하며, 배제에는 말초혈액 도말까지 포함한 혈구 검사(전혈구계산)와 응고 검사가 우선이고, 이상 시 혈액종양내과 대면 평가가 필요합니다. 이 답은 '배제해야 할 질환'과 '배제에 필요한 검사'에 한정하며, 병기·예후·치료는 다루지 않습니다.",
  "red_flag": {
    "present": false,
    "items": [
      {
        "id": "미확인",
        "evidence": "현재 입력에 HO1~HO9·R1~R12 해당 소견(항암 치료 중 발열, 멈추지 않는 출혈, 검은 변·토혈, 갑작스러운 숨참, 의식 변화, 척수 압박 시사 증상 등)이 확인되지 않음",
        "basis": "history"
      }
    ]
  },
  "hypotheses": [
    {
      "name": "급성 백혈병(골수성·림프구성)",
      "icd10": "C95",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "수 주간 피로 — 빈혈 시사", "basis": "history" },
        { "text": "자연 발생 멍 — 혈소판 감소 또는 응고 이상 시사", "basis": "history" },
        { "text": "무통성 림프절 종대 — 림프구성 백혈병·림프종성 침범과 부합", "basis": "history" }
      ],
      "against": [
        { "text": "발열·야간 발한·체중 감소·잇몸/코 출혈·점상출혈·골 통증·장기 비대 등 동반 소견이 확인되지 않음", "basis": "history" }
      ]
    },
    {
      "name": "림프종(호지킨·비호지킨, 골수 침범 동반 가능)",
      "icd10": "C81~C85",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "무통성 림프절 종대 — 림프종의 대표적 표현", "basis": "history" },
        { "text": "수 주간 피로 — 빈혈·전신 염증성 증상과 부합할 수 있음", "basis": "history" },
        { "text": "자연 발생 멍 — 골수 침범 또는 면역성 혈소판감소 동반 가능성", "basis": "history" }
      ],
      "against": [
        { "text": "B 증상(발열·야간 발한·6개월 내 10% 이상 체중 감소), 림프절 크기·단단함·고정 여부, 비장 비대가 확인되지 않음", "basis": "history" }
      ]
    },
    {
      "name": "골수형성이상증후군/골수부전",
      "icd10": "D46",
