      "against": [
        { "text": "점상출혈·잇몸 출혈·혈소판 수치가 확인되지 않음", "basis": "history" }
      ]
    },
    {
      "name": "감염(EBV·CMV·HIV, 결핵 등) 또는 약물에 의한 반응성 림프절 종대 + 혈구 이상",
      "icd10": "R59 / D69.5 등",
      "must_not_miss": false,
      "probability_band": "medium",
      "supports": [
