      ]
    },
    {
      "name": "철결핍·B12/엽산 결핍 등 영양성 빈혈",
      "icd10": "D50 / D51 / D52",
      "must_not_miss": false,
      "probability_band": "low",
      "supports": [
        { "text": "수 주간 피로", "basis": "history" }
      ],
      "against": [
        { "text": "자연 발생 멍은 영양성 빈혈만으로는 설명되지 않음", "basis": "history" }
      ]
    },
    {
      "name": "기타 응고 이상(파종성 혈관내 응고, 후천성 혈우병 등)",
      "icd10": "D65 / D68.3",
      "must_not_miss": true,
      "probability_band": "low",
      "supports": [
        { "text": "자연 발생 멍", "basis": "history" }
      ],
      "against": [
        { "text": "출혈 양상·감염·임신·악성 종양 병력이 확인되지 않음", "basis": "history" }
      ]
    }
  ],
  "missing_info": [
    "멍의 분포·개수·크기와 잇몸·코·소변·변 출혈 여부, 그리고 같은 부위 색 변화/외상 계기 (출혈 경향의 정도를 판별하는 단일 질문)"
  ],
  "suggested_tests": [
    { "name": "전혈구계산(CBC) + 말초혈액 도말", "purpose": "빈혈·혈소판 감소·비정상 세포(모세포) 확인 — 급성 백혈병/골수부전 배제의 1차", "urgency": "now", "basis": "guideline" },
    { "name": "응고 검사(PT/INR, aPTT, 피브리노겐, D-dimer 필요 시)", "purpose": "응고 이상·DIC 평가", "urgency": "now", "basis": "guideline" },
    { "name": "망상적혈구 수, LDH, 합토글로빈, 직접·간접 쿨롬스", "purpose": "용혈성 질환(혈전성 미세혈관병증 포함) 평가", "urgency": "24h", "basis": "guideline" },
    { "name": "신기능·간기능·전해질(Ca 포함), 요산, 인, K", "purpose": "종양 용해·고칼슘혈증 등 종양 응급 배제", "urgency": "24h", "basis": "guideline" },
    { "name": "경부 초음파 또는 필요 시 CT", "purpose": "림프절 크기·형태·분포 평가 및 조직 검사 표적 선정", "urgency": "24h", "basis": "guideline" },
    { "name": "림프절 절제 생검(총 생검 우선)", "purpose": "림프종 진단 — 세침흡인보다 절제 생검 권장", "urgency": "routine", "basis": "guideline" },
    { "name": "골수 흡인·생검", "purpose": "골수 침범/골수부전 평가(혈액종양내과 판단)", "urgency": "routine", "basis": "guideline" },
    { "name": "감염 선별(EBV, CMV, HIV, 결핵 등) — 임상 맥락에 따라", "purpose": "반응성 림프절 종대와 혈구 이상의 흔한 원인 평가", "urgency": "routine", "basis": "guideline" }
  ],
  "suggested_treatments": [
    {
      "kind": "referral",
      "description": "혈액종양내과 대면 평가 — 자연 발생 멍 + 무통성 림프절 종대 + 수 주간 피로의 조합은 악성 혈액질환을 배제할 수 없으므로, 검사 결과와 무관하게 대면 진료가 필요. 활력징후 불안정·활동성 출혈·고열 동반 시 응급실.",
