[SPECIALIST_FINDING]
{
  "specialty": "kdoctor-ent",
  "answer": "수 주간 지속되는 무통성 경부 림프절 종대는 이비인후과 영역에서 원발성 두경부 악성 종양(특히 상부 호흡소화관 편평상피암, 비인두·후두·하인두·구강·편도)에 의한 전이성 림프절이 우선 배제 대상이며, 원격 소견만으로는 확정할 수 없으나 종양 가능성을 전제로 한 대면 이비인후과 내시경 평가가 시급합니다. 동시에 결핵성 림프절염·감염성 단핵구증·림프종·자가면역/전신 원인도 감별에 포함되어야 합니다.",
  "red_flag": {
    "present": false,
    "items": [
      {
        "id": "ENT_H2_E5(부분)",
        "evidence": "무통성 경부 종대 자체는 심경부 감염(발열·압통·입 벌림 제한 등)의 전형적 신호는 아니나, 병력·진찰로 심경부 감염이 배제되지 않음",
        "basis": "history"
      },
      {
        "id": "ENT_H3_두경부악성종양",
        "evidence": "수 주(3주 이상) 지속 무통성 성인 경부 림프절 종대 — 두경부 원발 병소 탐색의 절대 적응",
        "basis": "history"
      }
    ]
  },
  "hypotheses": [
    {
      "name": "두경부 편평상피암의 경부 림프절 전이 (원발 미상 포함, occult primary)",
      "icd10": "C77.0",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "성인, 수 주간 지속 무통성 경부 림프절 종대 — 전이성 림프절의 전형적 양상", "basis": "history" },
        { "text": "전신 피로 — 진행성 종양·빈혈·영양 저하와 부합 가능", "basis": "history" }
      ],
      "against": [
        { "text": "연령·성별·흡연·음주력·직업력(목재·니켈 등) 미상 — 위험도 층화 불가", "basis": "history" },
        { "text": "림프절 위치(levels I–VI), 크기, 고정 여부, 점막 병변 유무 미확인", "basis": "history" }
      ]
    },
    {
      "name": "림프종 (호지킨/비호지킨) — 경부 림프절 우선 발현",
      "icd10": "C85 / C82–C86",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "무통성 림프절 종대 + 전신 피로 — B증상(발열·야간 발한·체중감소)의 일부와 겹칠 수 있음", "basis": "history" }
      ],
      "against": [
        { "text": "B증상(체중 감소·야간 발한·원인 불명 발열) 확인되지 않음", "basis": "history" },
        { "text": "림프절 분포(국소/전신), 크기, 압통 여부 미확인", "basis": "history" }
      ]
    },
    {
      "name": "결핵성 림프절염 (경부 결핵)",
      "icd10": "A18.2",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "수 주 지속 무통성 경부 림프절 종대 + 전신 피로 — 결핵성 림프절염의 전형적 경과", "basis": "history" }
      ],
      "against": [
        { "text": "기침·객혈·야간 발한·체중 감소·결핵 접촉력 확인되지 않음", "basis": "history" },
        { "text": "결핵 유병률 높은 지역 거주·방문력 미상", "basis": "history" }
      ]
