      "icd10": "B27.9 / B25.9 / B24 / B20",
      "must_not_miss": false,
      "probability_band": "medium",
      "supports": [
        { "text": "전신 피로 + 경부 림프절 종대", "basis": "history" }
      ],
      "against": [
        { "text": "인후통·발열·비장 비대·간효소 상승 등 미확인", "basis": "history" },
        { "text": "HIV 노출 위험력 미상", "basis": "history" }
      ]
    },
    {
      "name": "두경부의 국소 염증성 림프절 반응 (치성·인두·편도·피부 원인)",
      "icd10": "L04.0",
      "must_not_miss": false,
      "probability_band": "low",
      "supports": [
        { "text": "경부 림프절 종대 자체", "basis": "history" }
      ],
      "against": [
        { "text": "통증·압통·이환 부위 증상 없음(무통성)", "basis": "history" },
        { "text": "수 주간 지속은 급성 염증성 병태로는 비전형적", "basis": "history" }
      ]
    },
    {
      "name": "자가면역/전신 질환 (루푸스, 사르코이드증, Kikuchi병 등)",
      "icd10": "M32.9 / D86.9 / D76.3",
      "must_not_miss": false,
      "probability_band": "low",
      "supports": [
        { "text": "경부 림프절 종대 + 전신 피로", "basis": "history" }
      ],
      "against": [
        { "text": "관절통·발진·광과민·구강 궤양·장기 침범 소견 미확인", "basis": "history" }
      ]
    }
  ],
  "missing_info": [
    "림프절의 위치(좌·우/상·하 경부 level, 쇄골상 여부), 최대 크기, 고정 여부, 단일/다발성 여부 — 이 하나가 원발 부위 추정과 시급성 판단을 가장 크게 바꿉니다."
  ],
  "suggested_tests": [
    { "name": "경부 다중 슬라이스 CT (조영 증강)", "purpose": "림프절 levels·크기·괴사·주변 침범 평가, 원발 미상 림프절 전이에서 다음 단계(생검 부위 결정) 안내. 임신 가능성 확인 후 시행.", "urgency": "now", "basis": "guideline" },
    { "name": "전신 마취 하 상부 호흡소화관 내시경 (panendoscopy) 및 필요 시 조직 생검", "purpose": "비인두·구강·편도·하인두·후두·식도 상부의 원발 병소 탐색 및 조직 확정 진단", "urgency": "now", "basis": "guideline" },
